LogicDefinition.ScriptText:
#load "reference"
using FS.SDK.Components;
using System;
using System.Threading;
using System.Text;
using FS.SDK.Extensibility;
using FS.SDK.Util;

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Grob_GripperAddOn_MultiplePartTypes                                                  //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    23.06.2026       1.0.2          Egg              Ur Version
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              X              Egg              AddOn für unterschiedliche Werkstücktypen
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik wird als AddOn für die Grob_GripperBasic Logik verwendet zur Rückmeldung Gespannt mit
//    unterschiedlichen Werkstücktypen
//
//============================================================================================================
//
//    Input Slot Values
//    SIM_AddOnStatus               =   Byte, Gripper Status von Hauptlogik
//    SIM_PartPresent_TypeX         =   Bool, Teil Typ X vorhanden
//    PAR_ClampedPosition_TypeX     =   Real, Gespannt Position für Typ X
//    PAR_ClampedPosition_NoPart    =   Real, Gespannt Position für kein Teil
//
//    Output Slot Values
//    PLC_IN_Unclamped              =   Bool, Rückmeldung Greifer gelöst
//    PLC_IN_Clamped                =   Bool, Rückmeldung Greifer gespannt
//    PLC_IN_ClampedWithPart_TypeX  =   Bool, Rückmeldung Greifer gespannt mit Typ X
//    PLC_IN_ClampedWithoutPart     =   Bool, Rückmeldung Greifer gespannt ohne Teil
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////


#region Read-In Status Byte
//============================================================================================================
// R E A D - I N   S T A T U S   B Y T E 
//============================================================================================================

ConvertFunctions.ByteToBool(SIM_AddOnStatus,
out _statusBit0_unclamped,
out _statusBit1_clamped,
out _statusBit2_clampedWithPart,
out _statusBit3_clampedWithoutPart,
out _statusBit4,
out _statusBit5,
out _statusBit6,
out _statusBit7);


#endregion


#region Werte Schreiben
//============================================================================================================
// W E R T E   S C H R E I B E N   
//============================================================================================================

PLC_IN_Unclamped = _statusBit0_unclamped;
PLC_IN_Clamped = _statusBit1_clamped;

PLC_IN_ClampedWithPart_Type1 = _statusBit2_clampedWithPart && SIM_PartPresent_Type1;
PLC_IN_ClampedWithPart_Type2 = _statusBit2_clampedWithPart && SIM_PartPresent_Type2;
PLC_IN_ClampedWithPart_Type3 = _statusBit2_clampedWithPart && SIM_PartPresent_Type3;

PLC_IN_ClampedWithoutPart = _statusBit3_clampedWithoutPart;

#endregion


#region Clamped Position Schreiben
//============================================================================================================
// C L A M P E D   P  O S I T I O N   S C  H R E I B E N  
//============================================================================================================

if(SIM_PartPresent_Type1)
{
    SIM_TargetPosition = PAR_ClampedPosition_Type1;
}
else if(SIM_PartPresent_Type2)
{
    SIM_TargetPosition = PAR_ClampedPosition_Type2;
}
else if(SIM_PartPresent_Type3)
{
    SIM_TargetPosition = PAR_ClampedPosition_Type3;
}
else
{
    SIM_TargetPosition = PAR_ClampedPosition_NoPart;
}

#endregion
